  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a demand limit or minimum production requirement for each product, or can we produce any non-negative quantity of each product as long as the machine capacity constraints are satisfied?"
  ],
  "rationale": "The response asks a single clarification question regarding production bounds (limits/minimums vs. non-negative quantities), which constitutes one independent semantic request."
}

{
  "action": "question",
